```javascript
// secrets.js - Abstraction layer
class SecretsProvider {
  constructor() {
    this.provider = process.env.SECRETS_PROVIDER || 'env'; // env, aws, vault, azure, gcp

    if (this.provider === 'aws') {
      this.client = new AWS.SecretsManager();
    } else if (this.provider === 'vault') {
      this.client = require('node-vault')({ endpoint: process.env.VAULT_ADDR });
    }
  }

  async get(secretName) {
    switch (this.provider) {
      case 'aws':
        return this._getFromAWS(secretName);
      case 'vault':
        return this._getFromVault(secretName);
      case 'env':
      default:
        // Only for local development - warn in production
        if (process.env.NODE_ENV === 'production') {
          console.warn('WARNING: Using environment variables for secrets in production is insecure');
        }
        return process.env[secretName];
    }
  }

  async _getFromAWS(secretName) {
    const result = await this.client.getSecretValue({ SecretId: secretName }).promise();
    return JSON.parse(result.SecretString);
  }

  async _getFromVault(secretName) {
    const result = await this.client.read(`secret/data/${secretName}`);
    return result.data.data;
  }
}

module.exports = new SecretsProvider();
