// config/aws-secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const client = new SecretsManagerClient({ region: process.env.AWS_REGION });

const SECRET_ARN = process.env.SECRET_ARN; // Only this in env vars!

let cachedSecrets = null;
let lastFetch = 0;
const CACHE_TTL = 5 * 60 * 1000; // 5 minutes

const getSecrets = async () => {
  if (cachedSecrets && Date.now() - lastFetch < CACHE_TTL) {
    return cachedSecrets;
  }

  try {
    const response = await client.send(new GetSecretValueCommand({
      SecretId: SECRET_ARN,
    }));

    cachedSecrets = JSON.parse(response.SecretString);
    lastFetch = Date.now();

    return cachedSecrets;
  } catch (error) {
    console.error('Failed to fetch secrets:', error);
    throw error;
  }
};

// Middleware to inject secrets into request context
const secretsMiddleware = async (req, res, next) => {
  try {
    req.secrets = await getSecrets();
    next();
  } catch (error) {
    res.status(500).json({ error: 'Configuration error' });
  }
};

module.exports = { getSecrets, secretsMiddleware };
```

