// config/secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const secretsClient = new SecretsManagerClient({ 
  region: process.env.AWS_REGION || 'us-east-1' 
});

// Cache secrets for performance
const secretCache = new Map();
const CACHE_TTL = 5 * 60 * 1000; // 5 minutes

async function getSecret(secretName) {
  // Check cache first
  const cached = secretCache.get(secretName);
  if (cached && Date.now() - cached.timestamp < CACHE_TTL) {
    return cached.value;
  }

  try {
    const command = new GetSecretValueCommand({ SecretId: secretName });
    const response = await secretsClient.send(command);

    const secret = response.SecretString;

    // Parse JSON secrets (AWS style)
    let secretValue;
    try {
      secretValue = JSON.parse(secret);
    } catch {
      secretValue = secret; // Plain string secret
    }

    // Update cache
    secretCache.set(secretName, {
      value: secretValue,
      timestamp: Date.now()
    });

    return secretValue;
  } catch (error) {
    console.error(`Failed to retrieve secret ${secretName}:`, error);
    throw new Error('Secret retrieval failed');
  }
}

// Initialize all required secrets
async function loadSecrets() {
  const environment = process.env.NODE_ENV || 'development';

  const secretConfigs = {
    database: `myapp/${environment}/database`,
    stripe: `myapp/${environment}/stripe`,
    anthropic: `myapp/${environment}/anthropic`,
    aws: `myapp/${environment}/aws-credentials`,
    logfire: `myapp/${environment}/logfire`
  };

  const secrets = {};

  for (const [key, secretName] of Object.entries(secretConfigs)) {
    secrets[key] = await getSecret(secretName);
  }

  return secrets;
}

module.exports = { loadSecrets, getSecret };
```

