      }

    case 'development':
    case 'test':
    default:
      // In dev/test, use environment variables (from secure local config)
      return {
        databaseUrl: process.env.DATABASE_URL,
        jwtSecret: process.env.JWT_SECRET,
        awsAccessKeyId: process.env.AWS_ACCESS_KEY_ID,
        awsSecretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
        anthropicApiKey: process.env.ANTHROPIC_API_KEY,
        stripeSecretKey: process.env.STRIPE_SECRET_KEY,
      };
  }
}

/**
 * Validate that secrets are not using default/example values
 */
function validateSecrets(secrets) {
  const dangerousPatterns = [
    'CANARY',
    'your-',
    'example',
    'test-secret',
    'password123',
    'changeme',
    'admin',
    '123456',
    'secret',
    'default'
  ];

  const issues = [];

  for (const [key, value] of Object.entries(secrets)) {
    if (!value || typeof value !== 'string') continue;

    const lowerValue = value.toLowerCase();
    const matchesPattern = dangerousPatterns.some(pattern => 
      lowerValue.includes(pattern.toLowerCase())
    );

    if (matchesPattern) {
      issues.push(`Secret "${key}" appears to use a default/example value`);
    }

    // Check minimum entropy for secrets
    if (value.length < 16 && /(secret|key|token|password)/i.test(key)) {
      issues.push(`Secret "${key}" is too short (${value.length} chars, minimum 16)`);
    }
  }

  if (issues.length > 0) {
    console.error('❌ Secret validation failed:');
    issues.forEach(issue => console.error(`  - ${issue}`));
    throw new Error('Secret validation failed');
  }

  console.log('✅ Secrets validated successfully');
}

