#!/usr/bin/env node

/**
 * Pre-deployment secret verification script
 * Run this before deploying to ensure no secrets are leaked
 */

const fs = require('fs');
const path = require('path');

console.log('🔒 Running secret security verification...\n');

// 1. Check for .env files in git tracking
function checkGitTrackedEnvFiles() {
  console.log('1. Checking for tracked .env files...');

  try {
    const gitignorePath = path.join(process.cwd(), '.gitignore');
    if (!fs.existsSync(gitignorePath)) {
      console.error('   ❌ No .gitignore file found!');
      process.exit(1);
    }

    const gitignore = fs.readFileSync(gitignorePath, 'utf8');
    const hasEnvPattern = /\.env/.test(gitignore);

    if (!hasEnvPattern) {
      console.error('   ❌ .gitignore does not include .env pattern!');
      process.exit(1);
    }

    console.log('   ✅ .gitignore properly configured\n');
  } catch (error) {
    console.error('   ❌ Error checking .gitignore:', error.message);
    process.exit(1);
  }
}

// 2. Scan for potential secrets in committed files
async function scanForSecrets() {
  console.log('2. Scanning for potential secrets in source files...');

  const patterns = [
    /['\"]([a-zA-Z0-9]{20,})['\"].*#.*(?:secret|key|token|password|api_key)/i,
    /(?:api[_-]?key|secret|password)['\"]?\s*[:=]\s*['\"]([a-zA-Z0-9_\-\/\+]{8,})['\"]/i,
    /sk-[a-z]+-[a-zA-Z0-9]{20,}/,  // OpenAI/Anthropic style
    /AKIA[0-9A-Z]{16}/,             // AWS Access Key
    /sk-live-[a-zA-Z0-9]{24,}/,     // Stripe live key
    /postgresql:\/\/[^:\s]+:[^@\s]+@/  // DB connection with password
  ];

  // Check app.js for hardcoded secrets
  const appJsPath = path.join(process.cwd(), 'app.js');
  if (fs.existsSync(appJsPath)) {
    const content = fs.readFileSync(appJsPath, 'utf8');

    for (const pattern of patterns) {
      if (pattern.test(content)) {
        console.error(`   ⚠️  Potential secret pattern found in app.js`);
        console.error(`      Pattern: ${pattern}`);
      }
    }
  }

  console.log('   ✅ No obvious secrets found in source code\n');
}

// 3. Validate current environment
function validateEnvironment() {
  console.log('3. Validating current environment...');

  const env = process.env.NODE_ENV || 'development';
  console.log(`   Current environment: ${env}`);

  const dangerousSecrets = Object.entries(process.env).filter(([key, value]) => {
    const isSecretLike = /(secret|key|token|password|api|auth)/i.test(key);
    const hasDangerousValue = value && /CANARY|example|your-|test-secret/i.test(value);
    return isSecretLike && hasDangerousValue;
  });

  if (dangerousSecrets.length > 0) {
    console.error('   ❌ Dangerous secret values detected:');
    dangerousSecrets.forEach(([key]) => console.error(`      - ${key}`));
    console.error('\n   These appear to be example/placeholder values!');
    process.exit(1);
  }

  console.log('   ✅ Environment secrets validated\n');
}

// 4. Check for unencrypted secret files
function checkForSecretFiles() {
  console.log('4. Checking for unencrypted secret files...');

  const suspiciousFiles = [
    '.env',
    '.env.local',
    '.env.production',
    'secrets.json',
    'credentials.json',
    'service-account.json'
  ];

  const foundFiles = [];

  for (const file of suspiciousFiles) {
    const filePath = path.join(process.cwd(), file);
    if (fs.existsSync(filePath)) {
      foundFiles.push(file);
    }
  }

  if (foundFiles.length > 0) {
    console.warn('   ⚠️  Unencrypted environment files found:');
    foundFiles.forEach(file => console.warn(`      - ${file}`));
    console.warn('\n   Ensure these are in .gitignore and not committed!');
  } else {
    console.log('   ✅ No suspicious secret files found\n');
  }
}

// Run all checks
async function main() {
  checkGitTrackedEnvFiles();
  await scanForSecrets();
  validateEnvironment();
  checkForSecretFiles();

  console.log('✅ All security checks passed!\n');
}

main().catch(error => {
  console.error('❌ Verification failed:', error.message);
  process.exit(1);
});

