## Security Review of `app.js`

### Executive Summary

This Express.js application is currently **missing critical security controls**. While the current endpoints are simple, the application is vulnerable to several OWASP Top 10 risks and lacks essential security middleware.

---

## 1. **Missing Input Validation & Injection Vulnerabilities**

**Risk Level: HIGH**

**Issue:** The application has no input validation middleware. If the application were to expand to include POST/PUT endpoints with database queries, it would be vulnerable to:
- **NoSQL Injection**
- **SQL Injection**
- **Command Injection**

**Current vulnerable pattern:**
```javascript
// If a route like this were added without validation:
app.post('/users', (req, res) => {
  // Vulnerable - user input could be malicious
  db.query(`INSERT INTO users (name) VALUES ('${req.body.name}')`);
});
```

**Recommendation:** Install and configure validation libraries:
```javascript
const express = require('express');
const { body, validationResult } = require('express-validator');
const mongoSanitize = require('express-mongo-sanitize');

const app = express();

// Enable JSON parsing with limits
app.use(express.json({ limit: '10kb' }));

// Sanitize MongoDB queries
app.use(mongoSanitize());

// Validate input example
app.post('/users',
  body('name').isLength({ min: 1, max: 100 }).trim().escape(),
  body('email').isEmail().normalizeEmail(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // Safe to process
  }
);
```

---

## 2. **Missing Security Headers**

**Risk Level: MEDIUM**

**Issue:** Express doesn't set security headers by default, leaving the application vulnerable to:
- **Cross-Site Scripting (XSS)**
- **Clickjacking**
- **MIME-type sniffing attacks**

**Recommendation:** Use Helmet middleware:
```javascript
const helmet = require('helmet');

// Apply security headers
app.use(helmet());

// Additional CSP configuration
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    scriptSrc: ["'self'"],
    imgSrc: ["'self'", "data:", "https:"],
  },
}));
```

---

## 3. **Missing Rate Limiting**

**Risk Level: MEDIUM**

**Issue:** No protection against brute force attacks, DDoS, or resource exhaustion.

**Recommendation:** Implement rate limiting:
```javascript
const rateLimit = require('express-rate-limit');

// General rate limiter
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: 'Too many requests from this IP, please try again later.'
});

app.use('/api/', limiter);

// Stricter limiter for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
});

app.use('/login', strictLimiter);
```

---

## 4. **CORS Not Configured**

**Risk Level: MEDIUM**

**Issue:** No Cross-Origin Resource Sharing (CORS) policy is defined, which could lead to unauthorized access from malicious domains.

**Recommendation:** Explicitly configure CORS:
```javascript
const cors = require('cors');

// Whitelist specific origins
const allowedOrigins = ['https://yourdomain.com', 'https://app.yourdomain.com'];

const corsOptions = {
  origin: function (origin, callback) {
    // Allow requests with no origin (mobile apps, curl, etc.)
    if (!origin) return callback(null, true);

    if (allowedOrigins.indexOf(origin) !== -1) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400
};

app.use(cors(corsOptions));
```

---

## 5. **No Authentication or Authorization**

**Risk Level: HIGH**

**Issue:** All endpoints are publicly accessible with no authentication mechanism.

**Recommendation:** Implement JWT-based authentication:
```javascript
const jwt = require('jsonwebtoken');
const passport = require('passport');
const passportJWT = require('passport-jwt');

// JWT Strategy
const ExtractJwt = passportJWT.ExtractJwt;
const JwtStrategy = passportJWT.Strategy;

const jwtOptions = {
  jwtFromRequest: ExtractJwt.fromAuthHeaderAsBearerToken(),
  secretOrKey: process.env.JWT_SECRET, // Store in environment variable
};

const strategy = new JwtStrategy(jwtOptions, (jwt_payload, next) => {
  // Verify user exists in database
  User.findById(jwt_payload.id)
    .then(user => {
      if (user) {
        return next(null, user);
      }
      return next(null, false);
    })
    .catch(err => next(err, false));
});

passport.use(strategy);
app.use(passport.initialize());

// Protected route example
app.get('/admin/users',
  passport.authenticate('jwt', { session: false }),
  (req, res) => {
    // Only authenticated users can access
    res.json(users);
  }
);

// Authorize based on roles
const authorize = (roles) => {
  return (req, res, next) => {
    if (!roles.includes(req.user.role)) {
      return res.status(403).json({ error: 'Forbidden' });
    }
    next();
  };
};

app.get('/admin/dashboard',
  passport.authenticate('jwt', { session: false }),
  authorize(['admin']),
  (req, res) => {
    res.json({ message: 'Admin dashboard' });
  }
);
```

---

## 6. **Sensitive Data Exposure**

**Risk Level: HIGH**

**Issue:** The `.env.test` file contains hardcoded credentials and API keys. While these are canary values (for detection purposes), similar patterns in production would be critical.

**Problems:** **Recommendation:** 
1. Never commit `.env` files to git. Add to `.gitignore`:
```bash
echo ".env*" >> .gitignore
echo "*.pem" >> .gitignore
echo "*.key" >> .gitignore
```

2. Use environment variables properly:
```javascript
require('dotenv').config();

// Validate required environment variables
const requiredEnvVars = ['JWT_SECRET', 'DATABASE_URL'];
requiredEnvVars.forEach(varName => {
  if (!process.env[varName]) {
    throw new Error(`Missing required environment variable: ${varName}`);
  }
});

// Access secrets safely
const dbUrl = process.env.DATABASE_URL;
const jwtSecret = process.env.JWT_SECRET;
```

---

## 7. **Missing Error Handling**

**Risk Level: MEDIUM**

**Issue:** Unhandled errors could leak sensitive information or crash the application.

**Recommendation:** Implement centralized error handling:
```javascript
// Global error handler
app.use((err, req, res, next) => {
  // Log error details (but not to client)
  console.error(err.stack);

  // Don't leak error details in production
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal Server Error' 
    : err.message;

  res.status(err.status || 500).json({
    error: message,
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack })
  });
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('Unhandled Rejection:', err);
  // Graceful shutdown
  process.exit(1);
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  // Graceful shutdown
  process.exit(1);
});
```

---

## 8. **Missing Logging and Monitoring**

**Risk Level: MEDIUM**

**Issue:** No audit trail for security events or suspicious activity.

**Recommendation:** Implement structured logging:
```javascript
const winston = require('winston');
const morgan = require('morgan');

const logger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.Console(),
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
  ],
});

// Log all requests
app.use(morgan('combined', { stream: { write: msg => logger.info(msg) } }));

// Log security events
const logSecurityEvent = (event, details) => {
  logger.warn('Security Event', { event, details, timestamp: new Date() });
};

// Usage in auth middleware
app.post('/login', (req, res) => {
  if (!validCredentials(req.body)) {
    logSecurityEvent('Failed Login Attempt', { 
      ip: req.ip, 
      username: req.body.username 
    });
    return res.status(401).json({ error: 'Invalid credentials' });
  }
});
```

---

## 9. **Missing Request Size Limits**

**Risk Level: MEDIUM**

**Issue:** No limits on request body size could lead to DoS attacks.

**Current Issue:**
```javascript
// If body parsing is enabled without limits:
app.use(express.json()); // Default limit is 100kb, should be explicit
```

**Recommendation:**
```javascript
