// config/secrets.js
const crypto = require('crypto');

class SecretsManager {
  constructor() {
    this.secrets = {};
    this.loadOrder = [];
  }

  // Load from environment variables with validation
  loadFromEnv() {
    this.loadOrder.push('environment');

    const requiredSecrets = [
      'DATABASE_URL',
      'JWT_SECRET',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY'
    ];

    const optionalSecrets = [
      'ANTHROPIC_API_KEY',
      'STRIPE_SECRET_KEY',
      'LOGFIRE_TOKEN',
      'INTERNAL_HEALTH_KEY'
    ];

    // Load and validate required secrets
    for (const key of requiredSecrets) {
      const value = process.env[key];
      if (!value) {
        throw new Error(`Required secret ${key} is not set`);
      }
      this.secrets[key] = value;
    }

    // Load optional secrets
    for (const key of optionalSecrets) {
      if (process.env[key]) {
        this.secrets[key] = process.env[key];
      }
    }

    this.validateSecrets();
  }

  // Future: Load from AWS Secrets Manager
  async loadFromAWSSecretsManager(secretName, region) {
    const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

    const client = new SecretsManagerClient({ region });
    const command = new GetSecretValueCommand({ SecretId: secretName });

    try {
      const response = await client.send(command);
      const secrets = JSON.parse(response.SecretString);
      this.secrets = { ...this.secrets, ...secrets };
      this.loadOrder.push('aws-secrets-manager');
      return secrets;
    } catch (error) {
      throw new Error(`Failed to load secrets from AWS: ${error.message}`);
    }
  }

  // Future: Load from Azure Key Vault
  async loadFromAzureKeyVault(vaultName) {
    const { SecretClient } = require('@azure/keyvault-secrets');
    const { DefaultAzureCredential } = require('@azure/identity');

    const credential = new DefaultAzureCredential();
    const client = new SecretClient(`https://${vaultName}.vault.azure.net`, credential);

    const secrets = {};
    for await (const secretProperties of client.listPropertiesOfSecrets()) {
      const secret = await client.getSecret(secretProperties.name);
      secrets[secret.name.toUpperCase().replace(/-/g, '_')] = secret.value;
    }

    this.secrets = { ...this.secrets, ...secrets };
    this.loadOrder.push('azure-key-vault');
    return secrets;
  }

  // Future: Load from HashiCorp Vault
  async loadFromVault(path, options = {}) {
    const vault = require('node-vault')({
      apiVersion: 'v1',
      endpoint: options.endpoint || process.env.VAULT_ADDR,
      token: options.token || process.env.VAULT_TOKEN
    });

    try {
      const result = await vault.read(path);
      this.secrets = { ...this.secrets, ...result.data };
      this.loadOrder.push('hashicorp-vault');
      return result.data;
    } catch (error) {
