### AWS Secrets Manager Integration Script

```javascript
// scripts/setup-secrets.js
#!/usr/bin/env node

const { SecretsManagerClient, CreateSecretCommand, PutSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const REGION = process.env.AWS_REGION || 'us-east-1';
const SECRET_NAME = 'production/myapp';

const secrets = {
  DATABASE_URL: process.env.DATABASE_URL,
  JWT_SECRET: process.env.JWT_SECRET,
  AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
  // ... other secrets
};

async function setupSecrets() {
  const client = new SecretsManagerClient({ region: REGION });

  try {
    // Create or update secret
    const command = new PutSecretValueCommand({
      SecretId: SECRET_NAME,
      SecretString: JSON.stringify(secrets)
    });

    await client.send(command);
    console.log(`Secret ${SECRET_NAME} updated successfully`);
  } catch (error) {
    if (error.name === 'ResourceNotFoundException') {
      // Create new secret
      const createCommand = new CreateSecretCommand({
        Name: SECRET_NAME,
        SecretString: JSON.stringify(secrets),
        Description: 'Application secrets for production'
      });

      await client.send(createCommand);
      console.log(`Secret ${SECRET_NAME} created successfully`);
    } else {
      console.error('Failed to setup secrets:', error);
      process.exit(1);
    }
  }
}

setupSecrets();
```

