});
```

#### Option 2: HashiCorp Vault

```javascript
// config/vault.js
const vault = require('node-vault')({
  apiVersion: 'v1',
  endpoint: process.env.VAULT_ADDR,
  token: process.env.VAULT_TOKEN // This one env var is acceptable for Vault auth
});

async function loadSecretsFromVault(path) {
  try {
    const { data } = await vault.read(`secret/data/${path}`);
    return data.data;
  } catch (error) {
    console.error('Vault read failed:', error);
    throw error;
  }
}

module.exports = { loadSecretsFromVault };
```

#### Option 3: Kubernetes Secrets (if running in K8s)

```javascript
// In Kubernetes, mount secrets as files
const fs = require('fs').promises;
const path = require('path');

async function loadSecretsFromK8s() {
  const secretsPath = '/etc/secrets';
  const secrets = {};

  try {
    const files = await fs.readdir(secretsPath);

    for (const file of files) {
      const content = await fs.readFile(path.join(secretsPath, file), 'utf8');
      secrets[file] = content.trim();
    }

    return secrets;
  } catch (error) {
    throw new Error('Failed to load Kubernetes secrets: ' + error.message);
  }
}
```

