#### 3. Add Secret Scanning Protection

```javascript
// middleware/security.js
const checkForSecretsInRequest = (req, res, next) => {
  const sensitivePatterns = [
    /sk-live-[a-zA-Z0-9]{24,}/,  // Stripe live keys
    /AKIA[0-9A-Z]{16}/,          // AWS Access Key ID
    /[0-9a-zA-Z/+]{40}/,         // Generic secret pattern
    /-----BEGIN (RSA |EC |DSA |OPENSSH )?PRIVATE KEY-----/,
  ];

  const body = JSON.stringify(req.body);

  for (const pattern of sensitivePatterns) {
    if (pattern.test(body)) {
      // Log security event but don't leak details
      console.error('SECURITY: Potential secret detected in request body');
      return res.status(400).json({ 
        error: 'Request contains potentially sensitive data' 
      });
    }
  }

  next();
};

module.exports = { checkForSecretsInRequest };
```

